@@ -29,4 +29,39 @@
 <div class="moves-section"><div class="section-label">Move record</div><div class="move-list" id="move-list"><div class="move-empty">Your moves will appear here.</div></div><div class="section-label">How to move in 3D</div><p class="rules"><strong>Rook</strong> slides along any axis · <strong>Bishop</strong> diagonals across two axes · <strong>Knight</strong> jumps 2 + 1 · <strong>Queen</strong> any straight 3D line · <strong>King</strong> one cell in any direction. <strong>Pawns</strong> advance forward; capture diagonally across depth too. Reach the far rank to promote.</p></div></div></aside></main>
 <div class="footer-note">A THREE-DIMENSIONAL CHESS VARIANT &nbsp;·&nbsp; KINGS ARE NEVER CAPTURED &nbsp;·&nbsp; CHECKMATE WINS</div>
 </div>
 <script>
+const SIZE=8, TOTAL=512;
+const files='ABCDEFGH', symbols={white:{king:'♔',queen:'♕',rook:'♖',bishop:'♗',knight:'♘',pawn:'♙'},black:{king:'♚',queen:'♛',rook:'♜',bishop:'♝',knight:'♞',pawn:'♟'}};
+const value={pawn:1,knight:3,bishop:3,rook:5,queen:9,king:100};
+let board=Array(TOTAL).fill(null), turn='white', layer=0, selected=null, legal=[], lastMove=null, history=[], moves=[], cpu=true, aiBusy=false, terminal=null, ply=0;
+const boardEl=document.querySelector('#board'), layerEl=document.querySelector('#layers');
+const at=(x,y,z)=>x<0||x>7||y<0||y>7||z<0||z>7?-1:z*64+y*8+x;
+const xyz=i=>({x:i%8,y:Math.floor(i/8)%8,z:Math.floor(i/64)});
+const coord=i=>{const p=xyz(i);return `${files[p.x]}${p.y+1}@${p.z}`};
+const pieceAt=(x,y,z)=>{const i=at(x,y,z);return i<0?null:board[i]};
+function setup(){board=Array(TOTAL).fill(null);const back=['rook','knight','bishop','queen','king','bishop','knight','rook'];for(let x=0;x<8;x++){board[at(x,0,0)]={kind:back[x],color:'white',moved:false};board[at(x,1,1)]={kind:'pawn',color:'white',moved:false};board[at(x,6,6)]={kind:'pawn',color:'black',moved:false};board[at(x,7,7)]={kind:back[x],color:'black',moved:false};}turn='white';selected=null;legal=[];lastMove=null;history=[];moves=[];terminal=null;ply=0;aiBusy=false;layer=0;render();setStatus('Choose a piece to begin.');}
+function directions(kind){const out=[];for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++)for(let dz=-1;dz<=1;dz++){const n=(dx!==0)+(dy!==0)+(dz!==0);if(!n)continue;if(kind==='rook'&&n!==1)continue;if(kind==='bishop'&&n!==2)continue;out.push([dx,dy,dz]);}return out;}
+function rawMoves(i,attackOnly=false){const p=board[i];if(!p)return[];const {x,y,z}=xyz(i), result=[];const add=j=>{if(j>=0)result.push(j);};
+ if(p.kind==='pawn'){const d=p.color==='white'?1:-1;for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++){if(dx===0&&dz===0)continue;const j=at(x+dx,y+d,z+dz);if(j>=0&&(attackOnly||board[j]&&board[j].color!==p.color))add(j);}if(attackOnly)return result;const one=at(x,y+d,z);if(one>=0&&!board[one]){add(one);const start=p.color==='white'?1:6,two=at(x,y+2*d,z);if(y===start&&!p.moved&&two>=0&&!board[two])add(two);}return result;}
+ if(p.kind==='knight'){for(const a of [-2,-1,1,2])for(const b of [-2,-1,1,2])if(Math.abs(a)!==Math.abs(b))for(const [dx,dy,dz] of [[a,b,0],[a,0,b],[0,a,b]]){const j=at(x+dx,y+dy,z+dz);if(j>=0&&(!board[j]||board[j].color!==p.color))add(j);}return result;}
+ if(p.kind==='king'){for(const [dx,dy,dz] of directions('queen')){const j=at(x+dx,y+dy,z+dz);if(j>=0&&(!board[j]||board[j].color!==p.color))add(j);}return result;}
+ const dirs=directions(p.kind==='queen'?'queen':p.kind);for(const [dx,dy,dz] of dirs){let nx=x+dx,ny=y+dy,nz=z+dz;while(true){const j=at(nx,ny,nz);if(j<0)break;if(!board[j])add(j);else{if(board[j].color!==p.color)add(j);break;}nx+=dx;ny+=dy;nz+=dz;}}return result;
+}
+function simulate(from,to){const moving=board[from],taken=board[to],wasMoved=moving.moved,wasKind=moving.kind;board[to]=moving;board[from]=null;moving.moved=true;const q=xyz(to);if(moving.kind==='pawn'&&(q.y===0||q.y===7))moving.kind='queen';return()=>{moving.moved=wasMoved;moving.kind=wasKind;board[from]=moving;board[to]=taken;};}
+function kingIndex(color){return board.findIndex(p=>p&&p.color===color&&p.kind==='king');}
+function inCheck(color){const k=kingIndex(color);if(k<0)return false;const foe=color==='white'?'black':'white';for(let i=0;i<TOTAL;i++)if(board[i]&&board[i].color===foe)if(rawMoves(i,board[i].kind==='pawn').includes(k))return true;return false;}
+function legalMoves(i){const p=board[i];if(!p)return[];return rawMoves(i).filter(to=>{if(board[to]?.kind==='king')return false;const undo=simulate(i,to),safe=!inCheck(p.color);undo();return safe;});}
+function allLegal(color){const out=[];for(let i=0;i<TOTAL;i++)if(board[i]?.color===color)for(const to of legalMoves(i))out.push({from:i,to});return out;}
+function setStatus(text,alert=false){const el=document.querySelector('#status');el.textContent=text;el.classList.toggle('alert',alert);}
+function refreshStatus(){if(terminal){setStatus(terminal.text,terminal.alert);return;}if(aiBusy){setStatus('Computer is considering the whole cube…');return;}const check=inCheck(turn);setStatus(check?`${turn==='white'?'White':'Black'} king is in check — find a safe move.`:`${turn==='white'?'White':'Black'} to move. ${selected!==null?'Choose a highlighted square.':'Select a piece to reveal its 3D moves.'}`,check);}
+function render(){boardEl.innerHTML='';for(let y=7;y>=0;y--)for(let x=0;x<8;x++){const i=at(x,y,layer),p=board[i],button=document.createElement('button');button.type='button';button.className=`square ${(x+y)%2===0?'light':'dark'}`;button.setAttribute('role','gridcell');button.setAttribute('aria-label',`${coord(i)}${p?`, ${p.color} ${p.kind}`:''}`);button.dataset.index=i;if((selected===i))button.classList.add('selected');if(lastMove&&(lastMove.from===i||lastMove.to===i))button.classList.add('last');if(p?.kind==='king'&&p.color===turn&&inCheck(turn))button.classList.add('check');if(legal.includes(i))button.classList.add('legal',p?'capture':'');if(x===0){const label=document.createElement('span');label.className='coord';label.textContent=y+1;button.append(label);}if(p){const glyph=document.createElement('span');glyph.className=`piece ${p.color}`;glyph.textContent=symbols[p.color][p.kind];button.append(glyph);}button.addEventListener('click',()=>onSquare(i));boardEl.append(button);}
+ layerEl.innerHTML='';for(let z=7;z>=0;z--){const b=document.createElement('button');b.className=`layer-btn ${layer===z?'active':''} ${board.slice(z*64,(z+1)*64).some(Boolean)?'occupied':''}`;b.textContent=z;b.title=`Show depth level ${z}`;b.setAttribute('aria-label',`Show depth level ${z}`);b.addEventListener('click',()=>{layer=z;render();});layerEl.append(b);}document.querySelector('#level-readout').textContent=`LEVEL ${layer}`;document.querySelector('#board-subtitle').textContent=`LEVEL ${layer}  ·  X / Y PLANE`;document.querySelector('#cube-level').textContent=`Z ${layer}`;document.querySelector('#cube-slice').style.transform=`translateY(${(3.5-layer)*2}px)`;document.querySelector('#turn-name').textContent=turn==='white'?'White':'Black';document.querySelector('#turn-token').textContent=turn==='white'?'♔':'♚';document.querySelector('#turn-token').classList.toggle('black',turn==='black');document.querySelector('#turn-count').textContent=`MOVE ${Math.floor(ply/2)+1}`;document.querySelector('#move-list').innerHTML=moves.length?moves.map((m,i)=>`<div class="move-row"><span class="n">${Math.floor(i/2)+1}.</span><span class="white-m">${moves[i]||''}</span><span class="black-m">${moves[i+1]||''}</span></div>`).join(''):'<div class="move-empty">Your moves will appear here.</div>';const list=document.querySelector('#move-list');list.scrollTop=list.scrollHeight;document.querySelector('#interaction-hint').innerHTML=selected!==null?`<strong>${coord(selected)}</strong> selected · pick a highlighted destination`:`<strong>Select a piece</strong> to reveal its 3D moves`;document.querySelector('.live span').textContent=terminal?'Game complete':aiBusy?'Computer thinking':'Game in progress';document.querySelector('#undo-btn').disabled=history.length===0;}
+function onSquare(i){if(terminal||aiBusy||(cpu&&turn==='black'))return;if(selected!==null&&legal.includes(i)){makeMove(selected,i);return;}if(board[i]?.color===turn){selected=i;legal=legalMoves(i);if(!legal.length)setStatus('No safe moves for that piece. Try another.');else refreshStatus();render();return;}if(selected!==null){selected=null;legal=[];refreshStatus();render();}}
+function makeMove(from,to){const mover=board[from],captured=board[to],start=coord(from),end=coord(to);history.push({board:board.map(p=>p?{...p}:null),turn,ply,lastMove,moves:[...moves]});board[to]=mover;board[from]=null;mover.moved=true;let suffix=captured?'×':'';if(mover.kind==='pawn'&&(xyz(to).y===0||xyz(to).y===7)){mover.kind='queen';suffix+='=Q';}lastMove={from,to};moves.push(`${symbols[mover.color][mover.kind]} ${start}→${end}${suffix}`);ply++;turn=turn==='white'?'black':'white';layer=xyz(to).z;selected=null;legal=[];terminal=null;const options=allLegal(turn);if(!options.length){if(inCheck(turn))terminal={text:`Checkmate — ${turn==='white'?'Black':'White'} wins.`,alert:true};else terminal={text:'Stalemate — the game is a draw.',alert:false};}render();refreshStatus();if(cpu&&turn==='black'&&!terminal){aiBusy=true;render();refreshStatus();setTimeout(computerMove,520);}}
+function computerMove(){if(terminal)return;const options=allLegal('black');if(!options.length){aiBusy=false;return;}let best=-Infinity,choice=options[0];for(const m of options){const target=board[m.to],undo=simulate(m.from,m.to);let score=(target?value[target.kind]*1.3:0)+(board[m.to].kind==='queen'&&target?.kind!=='queen'?0.5:0);if(inCheck('white'))score+=1.3;const pos=xyz(m.to);score+=(3.5-Math.abs(3.5-pos.x))*.035+(Math.random()*.55);undo();if(score>best){best=score;choice=m;}}aiBusy=false;makeMove(choice.from,choice.to);}
+function undo(){if(!history.length||aiBusy)return;let n=1;if(cpu&&turn==='white'&&history.length>=2)n=2;while(n--&&history.length){const s=history.pop();board=s.board;turn=s.turn;ply=s.ply;lastMove=s.lastMove;moves=s.moves;}selected=null;legal=[];terminal=null;layer=lastMove?xyz(lastMove.to).z:0;const options=allLegal(turn);if(!options.length)terminal=inCheck(turn)?{text:`Checkmate — ${turn==='white'?'Black':'White'} wins.`,alert:true}:{text:'Stalemate — the game is a draw.',alert:false};render();refreshStatus();}
+document.querySelector('#prev-layer').addEventListener('click',()=>{layer=Math.min(7,layer+1);render();});document.querySelector('#next-layer').addEventListener('click',()=>{layer=Math.max(0,layer-1);render();});document.querySelector('#undo-btn').addEventListener('click',undo);document.querySelector('#new-btn').addEventListener('click',setup);document.querySelector('#cpu-mode').addEventListener('click',()=>{cpu=true;document.querySelector('#cpu-mode').classList.add('active');document.querySelector('#local-mode').classList.remove('active');setup();});document.querySelector('#local-mode').addEventListener('click',()=>{cpu=false;document.querySelector('#local-mode').classList.add('active');document.querySelector('#cpu-mode').classList.remove('active');setup();});
+setup();
+</script>
+</body>
+</html>

